toad_implementation.code_blueprint:
canvas {
  size: 700px 920px;
  fill: #241E1A;
  font-family: "Alegreya, serif";
}

>cask = #241E1A;
>copper = #C08A3E;
>labelPaper = #EFE8DC;
>wineRed = #4A1E23;

rect #bottleLabel {
  at: center of canvas;
  size: 520px 760px;
  fill: >labelPaper;
  stroke: >copper;
  stroke-width: 2px;
  radius: 8px;
}

rect #innerEtchRing {
  at: center of #bottleLabel;
  size: 488px 728px;
  fill: none;
  stroke: >copper;
  stroke-width: 1px;
}

circle #crestMedallion {
  at: top center of #bottleLabel offset 0px 80px;
  size: 90px;
  fill: >wineRed;
  stroke: >copper;
  stroke-width: 2px;
}

text #crestLetter {
  at: center of #crestMedallion;
  content: "V";
  font-size: 48px;
  color: >copper;
}

text #estateName {
  at: below #crestMedallion offset 40px;
  content: "V I N A   V A L D E P E Ñ A S";
  font-size: 20px;
  font-weight: 700;
  color: >cask;
}

text #wineVariety {
  at: below #estateName offset 12px;
  content: "GRAN RESERVA TEMPRANILLO";
  font-size: 13px;
  font-weight: 700;
  color: >copper;
}

text #vintageYear {
  at: below #wineVariety offset 24px;
  content: "—  2019  —";
  font-size: 24px;
  font-weight: 700;
  color: >wineRed;
}

text #regionAppellation {
  at: bottom center of #bottleLabel offset 0px -60px;
  content: "DENOMINACIÓN DE ORIGEN CALIFICADA • 14.5% VOL";
  font-size: 10px;
  color: #6B5E51;
}
